static void need(bool x,const char*m){if(!x)throw std::runtime_error(m);}
struct Values{double cost=0;std::vector<double>r,g;ceres::CRSMatrix J;};
static Values eval(JointALBuilder&b,ceres::Problem&p,const BuildInventory&inv){ceres::Problem::EvaluateOptions o;o.num_threads=1;for(auto x:inv.statistical_blocks)o.residual_blocks.push_back(static_cast<ceres::ResidualBlockId>(x));for(auto x:inv.inequality_blocks)o.residual_blocks.push_back(static_cast<ceres::ResidualBlockId>(x));for(auto x:inv.equality_blocks)o.residual_blocks.push_back(static_cast<ceres::ResidualBlockId>(x));need(o.residual_blocks.size()==std::size_t(p.NumResidualBlocks()),"inventory incomplete");for(const auto&v:b.parameter_blocks())if(p.HasParameterBlock(v.data)&&!p.IsParameterBlockConstant(v.data))o.parameter_blocks.push_back(v.data);Values v;need(p.Evaluate(o,&v.cost,&v.r,&v.g,&v.J),"fixture evaluation failed");return v;}
static void equal(const Values&a,const Values&b){need(a.cost==b.cost,"cost mismatch");need(a.r==b.r,"residual mismatch");need(a.g==b.g,"gradient mismatch");need(a.J.num_rows==b.J.num_rows&&a.J.num_cols==b.J.num_cols&&a.J.rows==b.J.rows&&a.J.cols==b.J.cols&&a.J.values==b.J.values,"full sparse J mismatch");}
int main(int argc,char**argv){try{if(argc!=3)throw std::runtime_error("MODEL OUT");auto m=JointEventModel::load(argv[1]);need(m.materials.at(0).paths.at(0).kind==6,"fixture needs actual kind6");m.materials={m.materials[0]};m.materials[0].paths={m.materials[0].paths[0]};m.source_json.erase("physical_equalities");m.source_json.erase("shared_print_shape_transition_v1");m.runtime_model_metadata.erase("confirmed_tripod_outside_rink_v1");m.source_json.erase("confirmed_tripod_outside_rink_v1");const auto&path=m.materials[0].paths[0];const int segments=int(path.vertex_blocks.size())-(path.closed?0:1);need(segments>4,"fixture contour too short");JointPacket packet;packet.source_hash="small_actual_local_factory_fixture";const std::vector<std::string>shots={"s01","s02","s03","s04","s05","s06"};packet.source_json={{"schema",packet.schema},{"runtime_current_input_v1",true},{"dense_source_binding",eventio::Json::object()},{"shot_ids",shots},{"engineering_scope",{{"schema","rinkfit.engineering_active_shots.v1"},{"shot_ids",shots},{"three_rigs_one_scene",true}}}};packet.rows.resize(3);for(std::size_t i=0;i<3;++i){auto&r=packet.rows[i];r.active=true;r.kind=0;r.material=0;r.path=0;r.shot_id="s06";r.pts=m.shots.at(m.shot_map.at("s06")).first_pts;r.row=539.5;r.E=2;r.station=i?3.5/segments:1./segments;r.numerical_shape_segment=i?3:0;r.source_dataset_id="numeric_fixture";r.source_row_id=std::to_string(i);r.source_print_identity_reviewed=true;r.source_finite_paths=std::make_shared<const std::vector<int>>(std::vector<int>{0});r.uv={400.+double(i),500.};}JointStatisticalGroup g;g.id="complete_group_01";g.statistic_kind="original";g.rows={0,1};g.rank=4;g.W={1,0,0.1,0,0,2,0,0.2,0,0,3,0,0,0,0,4};packet.groups.push_back(g);g.id="unaffected_group_2";g.rows={2};g.rank=2;g.W={2,0,0,3};packet.groups.push_back(g);
 eventio::Json cfg={{"source_uv_capture_objective","rinkfit.sourceUV_observed_row_finite_initialization.v1"},{"current_input_v1",eventio::Json::object()},{"observed_source_allowed_path_restart_v1",eventio::Json::object()},{"engineering_active_shot_ids",shots},{"physical_constraint_penalty",10.},{"pixel_total_weight",3.}};
 cfg["engineering_support_budget_v2"]={{"schema","rinkfit.native_exposure_material_budget.v2"},{"scheme","equal_native_exposure"},{"calibrated_covariance",false},{"source_packet_sha256",packet.source_hash},{"total_budget",3.}};
 packet.source_json["runtime_current_input_v1"]={{"binding",cfg.at("current_input_v1")}};
 packet.source_json["current_input_manifest_v1"]={{"version","in_memory_numeric_fixture"},{"logical_source_id",packet.source_hash},{"engineering_support_budget_v2",cfg.at("engineering_support_budget_v2")}};
 JointALBuilder b(m,packet,true,false,true);b.enable_source_uv_observed_row_initialization();ceres::Problem::Options po;po.enable_fast_removal=true;po.manifold_ownership=ceres::DO_NOT_TAKE_OWNERSHIP;ceres::Problem p(po);eventio::Json ledger;auto inv=b.build_engineering_problem(p,cfg,&ledger);auto initial=eval(b,p,inv);const auto stats=inv.statistical_blocks,ineq=inv.inequality_blocks;JointCollinearBoxWorkingSetV1 carriers(b,p);std::string reason;need(b.supports_observed_local_cell_rebind_v1({0},&reason),reason.c_str());auto edit=b.begin_observed_local_cell_rebind_v1(p,inv,{0},{0,1});b.core.packet.rows[0].numerical_shape_segment=1;b.bind_observed_local_rows_v1(p,inv,edit);carriers.remap_residuals_v1(edit.replacements);auto current=eval(b,p,inv);
 JointALBuilder fresh(b.core.model,b.core.packet,true,false,true);fresh.enable_source_uv_observed_row_initialization();fresh.core.station=b.core.station;fresh.core.row=b.core.row;fresh.core.alpha=b.core.alpha;ceres::Problem fp(po);eventio::Json fl;auto fi=fresh.build_engineering_problem(fp,cfg,&fl);equal(current,eval(fresh,fp,fi));need(ledger==fl,"row budgets changed");need(inv.statistical_blocks[2]==stats[2],"unaffected pixel replaced");std::size_t stable=0;for(std::size_t i=0;i<ineq.size();++i)if(inv.inequality_blocks[i]==ineq[i])++stable;need(stable>0,"all physical factors replaced");
 auto back=b.begin_observed_local_cell_rebind_v1(p,inv,{0},{0,1});b.core.packet.rows[0].numerical_shape_segment=0;b.bind_observed_local_rows_v1(p,inv,back);carriers.remap_residuals_v1(back.replacements);equal(initial,eval(b,p,inv));
 eventio::Json report={{"passed",true},{"raw_fixture_rows",3},{"changed_rows",1},{"complete_group_rows",2},{"unaffected_global_or_domain_RIDs",stable},{"residual_scalars",current.r.size()},{"gradient_scalars",current.g.size()},{"J_values",current.J.values.size()},{"local_vs_fresh_cost_residual_gradient_J","exact"},{"rollback_cost_residual_gradient_J","exact"},{"full_source_loaded",false},{"Solve_called",false}};std::ofstream(argv[2])<<report.dump(2);std::cout<<report.dump()<<std::endl;return 0;}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}}
